alter table supplier_payment add column if not exists bank_reference text,add column if not exists memo text,add column if not exists journal_id bigint references journal,add column if not exists currency_id bigint references currencies,add column if not exists exchange_rate numeric(24,10) not null default 1,add column if not exists fiscal_period_id bigint references fiscal_periods,add column if not exists location_id bigint references locations,add column if not exists status text not null default 'APROBADO',add column if not exists created_by bigint references users;
create index if not exists supplier_payment_report_scope_idx on supplier_payment(payment_date,supplier_id,bank_account_id);

create or replace function supplier_payment_options()returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('subsidiary',jsonb_build_object('id',s.subsidiary_id,'name',s.name,'currencyId',s.currency_id),'location',(select jsonb_build_object('id',l.location_id,'name',l.name)from locations l left join location_subsidiaries ls using(location_id)where l.subsidiary_id=s.subsidiary_id or ls.subsidiary_id=s.subsidiary_id order by l.location_id limit 1),'suppliers',coalesce((select jsonb_agg(jsonb_build_object('id',p.supplier_id,'name',p.company_name))from suppliers p join entity_subsidiaries es using(supplier_id)where es.subsidiary_id=s.subsidiary_id),'[]'),'accounts',coalesce((select jsonb_agg(jsonb_build_object('id',ba.bank_account_id,'bank',b.bank_name,'number',ba.account_number,'currencyId',ba.currency_id,'currency',c.currency_code,'balance',ba.balance))from bank_account ba join banks b using(bank_id)join currencies c using(currency_id)where ba.subsidiary_id=s.subsidiary_id and not coalesce(ba.is_credit_card,false)),'[]'),'periods',coalesce((select jsonb_agg(jsonb_build_object('id',fiscal_period_id,'name',period_name,'start',start_date,'end',end_date))from fiscal_periods where subsidiary_id=s.subsidiary_id and not is_closed),'[]'),'invoices',coalesce((select jsonb_agg(jsonb_build_object('id',i.invoice_id,'number',i.invoice_number,'supplierId',i.supplier_id,'date',i.invoice_date,'dueDate',i.due_date,'currencyId',i.currency_id,'currency',c.currency_code,'total',i.total_amount,'paid',coalesce(a.paid,0),'balance',greatest(i.total_amount-coalesce(a.paid,0),0)))from supplier_invoice i join currencies c on c.currency_id=i.currency_id left join lateral(select sum(amount)paid from supplier_payment_application where invoice_id=i.invoice_id)a on true where i.subsidiary_id=s.subsidiary_id and i.total_amount>coalesce(a.paid,0)),'[]'))from subsidiaries s where s.subsidiary_id=active_subsidiary_id()$$;

create or replace function save_supplier_payment(p_payload jsonb,p_payment_id bigint default null)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare sid bigint:=active_subsidiary_id();ba bank_account%rowtype;old supplier_payment%rowtype;item jsonb;total numeric:=0;outstanding numeric;tt bigint;st bigint;num text;tid bigint;jid bigint;pid bigint;ap bigint;d date:=(p_payload->>'date')::date;rate numeric:=(p_payload->>'rate')::numeric;period_key bigint:=(p_payload->>'period_id')::bigint;supplier_key bigint:=(p_payload->>'supplier_id')::bigint;begin
select*into ba from bank_account where bank_account_id=(p_payload->>'account_id')::bigint and subsidiary_id=sid for update;if ba.bank_account_id is null then raise exception'Seleccione una cuenta bancaria de la subsidiaria.';end if;if not exists(select 1 from fiscal_periods where fiscal_period_id=period_key and subsidiary_id=sid and d between start_date and end_date and not is_closed)then raise exception'No existe período abierto para la fecha.';end if;if nullif(trim(p_payload->>'reference'),'')is null then raise exception'Ingrese la referencia bancaria.';end if;
for item in select value from jsonb_array_elements(coalesce(p_payload->'applications','[]'))loop if(item->>'amount')::numeric<=0 then continue;end if;select greatest(i.total_amount-coalesce((select sum(a.amount)from supplier_payment_application a where a.invoice_id=i.invoice_id and(p_payment_id is null or a.payment_id<>p_payment_id)),0),0)into outstanding from supplier_invoice i where i.invoice_id=(item->>'invoice_id')::bigint and i.supplier_id=supplier_key and i.subsidiary_id=sid;if outstanding is null then raise exception'La factura no corresponde al proveedor.';end if;if(item->>'amount')::numeric>outstanding then raise exception'El pago de la factura supera su saldo pendiente de %.',round(outstanding,2);end if;total:=total+(item->>'amount')::numeric;end loop;if total<=0 then raise exception'Seleccione al menos una factura e indique el importe a pagar.';end if;
select account_id into ap from chart_accounts where category='Pasivo'and accepts_entries and not is_inactive and account_name~*'cuenta.*por pagar|proveedor'and(account_id in(select account_id from account_subsidiaries where subsidiary_id=sid and is_active)or not exists(select 1 from account_subsidiaries where subsidiary_id=sid))order by account_id limit 1;if ap is null then raise exception'No se encontró la cuenta contable de proveedores.';end if;
if p_payment_id is null then if ba.balance<total then raise exception'Saldo bancario insuficiente. Disponible %, requerido %.',round(ba.balance,2),round(total,2);end if;select transaction_type_id into tt from transaction_types where abbreviation='PAG_PRO';select status_id into st from status where code='APROBADO'limit 1;begin num:=next_transaction_number(tt,sid);exception when others then num:='PAG_PRO-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS');end;insert into"transaction"(tran_number,tran_date,transaction_type_id,subsidiary_id,currency_id,exchange_rate,fiscal_period_id,total_amount,status_id,supplier_id)values(num,d,tt,sid,ba.currency_id,rate,period_key,total,st,supplier_key)returning transaction_id into tid;insert into journal(journal_number,journal_date,transaction_id,subsidiary_id,currency_id,fiscal_period_id,exchange_rate,memo,journal_type,location_id,total_debit,total_credit,status)values(num,d,tid,sid,ba.currency_id,period_key,rate,p_payload->>'memo','PAGO_PROVEEDOR',nullif(p_payload->>'location_id','')::bigint,total,total,'CONTABILIZADO')returning journal_id into jid;insert into supplier_payment(payment_number,transaction_id,supplier_id,bank_account_id,payment_date,amount_paid,bank_reference,memo,journal_id,currency_id,exchange_rate,fiscal_period_id,location_id,created_by)values(num,tid,supplier_key,ba.bank_account_id,d,total,p_payload->>'reference',p_payload->>'memo',jid,ba.currency_id,rate,period_key,nullif(p_payload->>'location_id','')::bigint,app_user_id())returning payment_id into pid;else select*into old from supplier_payment where payment_id=p_payment_id and transaction_id in(select transaction_id from"transaction"where subsidiary_id=sid)for update;if old.payment_id is null then raise exception'Pago no encontrado.';end if;if ba.balance+old.amount_paid<total then raise exception'Saldo bancario insuficiente.';end if;pid:=old.payment_id;num:=old.payment_number;tid:=old.transaction_id;jid:=old.journal_id;update bank_account set balance=balance+old.amount_paid where bank_account_id=old.bank_account_id;delete from supplier_payment_application where payment_id=pid;delete from journal_line where journal_id=jid;update supplier_payment set supplier_id=supplier_key,bank_account_id=ba.bank_account_id,payment_date=d,amount_paid=total,bank_reference=p_payload->>'reference',memo=p_payload->>'memo',currency_id=ba.currency_id,exchange_rate=rate,fiscal_period_id=period_key,location_id=nullif(p_payload->>'location_id','')::bigint where payment_id=pid;update"transaction"set tran_date=d,currency_id=ba.currency_id,exchange_rate=rate,fiscal_period_id=period_key,total_amount=total,supplier_id=supplier_key where transaction_id=tid;update journal set journal_date=d,currency_id=ba.currency_id,exchange_rate=rate,fiscal_period_id=period_key,memo=p_payload->>'memo',total_debit=total,total_credit=total where journal_id=jid;update bank_transaction set tran_date=d,value_date=d,bank_account_id=ba.bank_account_id,amount=-total,reference_number=p_payload->>'reference',description=p_payload->>'memo'where transaction_id=tid;end if;
insert into journal_line(journal_id,account_id,debit,credit,debit_fx,credit_fx,location_id,note,entity_type,supplier_id)values(jid,ap,total,0,total*rate,0,nullif(p_payload->>'location_id','')::bigint,p_payload->>'memo','Proveedor',supplier_key),(jid,ba.account_id,0,total,0,total*rate,nullif(p_payload->>'location_id','')::bigint,p_payload->>'memo','Proveedor',supplier_key);for item in select value from jsonb_array_elements(p_payload->'applications')loop if(item->>'amount')::numeric>0 then insert into supplier_payment_application(payment_id,invoice_id,amount,application_date)values(pid,(item->>'invoice_id')::bigint,(item->>'amount')::numeric,d);end if;end loop;if p_payment_id is null then insert into bank_transaction(tran_date,value_date,bank_account_id,transaction_id,amount,tran_type,reference_number,description,beneficiary,reconciliation_status)values(d,d,ba.bank_account_id,tid,-total,'PAGO_PROVEEDOR',p_payload->>'reference',p_payload->>'memo',(select company_name from suppliers where supplier_id=supplier_key),'PENDIENTE_EN_TRANSITO');end if;update bank_account set balance=balance-total where bank_account_id=ba.bank_account_id;return jsonb_build_object('id',pid,'number',num,'journalId',jid,'total',total);end$$;

create or replace function supplier_payment_report(p_filters jsonb)returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('rows',coalesce(jsonb_agg(jsonb_build_object('id',p.payment_id,'number',p.payment_number,'date',p.payment_date,'supplier',s.company_name,'bank',b.bank_name,'account',ba.account_number,'currency',c.currency_code,'reference',p.bank_reference,'amount',p.amount_paid,'status',p.status)order by p.payment_date desc,p.payment_id desc),'[]'))from supplier_payment p join"transaction"t on t.transaction_id=p.transaction_id join suppliers s on s.supplier_id=p.supplier_id join bank_account ba on ba.bank_account_id=p.bank_account_id join banks b on b.bank_id=ba.bank_id join currencies c on c.currency_id=ba.currency_id where t.subsidiary_id=active_subsidiary_id()and p.payment_date between(p_filters->>'from')::date and(p_filters->>'to')::date$$;
create or replace function supplier_payment_detail(p_payment_id bigint)returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('header',to_jsonb(p)||jsonb_build_object('supplier',s.company_name,'bank',b.bank_name,'account',ba.account_number,'currency',c.currency_code,'subsidiary',sub.name,'location',l.name),'applications',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('invoiceNumber',i.invoice_number,'invoiceTotal',i.total_amount))from supplier_payment_application a join supplier_invoice i using(invoice_id)where a.payment_id=p.payment_id),'[]'),'impact',coalesce((select jsonb_agg(to_jsonb(jl)||jsonb_build_object('accountNumber',ca.account_number,'accountName',ca.account_name))from journal_line jl join chart_accounts ca using(account_id)where jl.journal_id=p.journal_id),'[]'))from supplier_payment p join"transaction"t on t.transaction_id=p.transaction_id join suppliers s on s.supplier_id=p.supplier_id join bank_account ba on ba.bank_account_id=p.bank_account_id join banks b on b.bank_id=ba.bank_id join currencies c on c.currency_id=ba.currency_id join subsidiaries sub on sub.subsidiary_id=t.subsidiary_id left join locations l on l.location_id=p.location_id where p.payment_id=p_payment_id and t.subsidiary_id=active_subsidiary_id()$$;
create or replace function delete_supplier_payment(p_payment_id bigint)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare p supplier_payment%rowtype;begin select sp.*into p from supplier_payment sp join"transaction"t using(transaction_id)where sp.payment_id=p_payment_id and t.subsidiary_id=active_subsidiary_id()for update;if p.payment_id is null then raise exception'Pago no encontrado.';end if;update bank_account set balance=balance+p.amount_paid where bank_account_id=p.bank_account_id;delete from bank_transaction where transaction_id=p.transaction_id;delete from supplier_payment where payment_id=p.payment_id;delete from journal_support where journal_id=p.journal_id;delete from journal_line where journal_id=p.journal_id;delete from journal where journal_id=p.journal_id;delete from"transaction"where transaction_id=p.transaction_id;return jsonb_build_object('success',true,'number',p.payment_number);end$$;
revoke all on function supplier_payment_options(),supplier_payment_report(jsonb),supplier_payment_detail(bigint),save_supplier_payment(jsonb,bigint),delete_supplier_payment(bigint)from public,anon;grant execute on function supplier_payment_options(),supplier_payment_report(jsonb),supplier_payment_detail(bigint),save_supplier_payment(jsonb,bigint),delete_supplier_payment(bigint)to authenticated;notify pgrst,'reload schema';
